from collections import Counter

def count_common(words):
    word_counts = Counter(words)
    return word_counts.most_common()

def split_lowerstring(text):
    result = []
    current_word = []
    for char in text:
        if char.islower():
            current_word.append(char)
        else:
            if current_word:
                result.append(''.join(current_word))
                current_word = []
    if current_word:
        result.append(''.join(current_word))
    return result

def remove_dirty_chars(string, second_string):
    chars_to_remove = set(second_string)
    return ''.join(char for char in string if char not in chars_to_remove)

def remove(list):
    result = []
    for s in list:
        new_s = ''.join([c for c in s if not c.isdigit()])
        result.append(new_s)
    return result

from math import factorial

def binomial_Coeff(n, k):
    if k < 0 or k > n:
        return 0
    return factorial(n) // (factorial(k) * factorial(n - k))

def decimal_To_Binary(N):
    if N == 0:
        return "0"
    binary = ""
    num = N
    while num > 0:
        binary = str(num % 2) + binary
        num = num // 2
    return binary

def div_even_odd(list1):
    first_even = None
    first_odd = None
    for num in list1:
        if num % 2 == 0:
            if first_even is None:
                first_even = num
        else:
            if first_odd is None:
                first_odd = num
        if first_even is not None and first_odd is not None:
            break
    if first_even is None or first_odd is None:
        return None
    return first_even / first_odd

from typing import List
from math import gcd
from functools import reduce

def get_gcd(l: List[int]) -> int:
    if not l:
        return 0
    return reduce(gcd, l)

def check_Equality(str):
    if len(str) == 0:
        return False
    return str[0] == str[-1]

def is_octagonal(n):
    if n < 8:
        return False
    discriminant = 1 + 24 * n
    sqrt_discriminant = int(discriminant ** 0.5)
    if sqrt_discriminant * sqrt_discriminant != discriminant:
        return False
    if (sqrt_discriminant + 1) % 8 != 0:
        return False
    return True

def pos_count(list):
    count = 0
    for num in list:
        if num > 0:
            count += 1
    return count

def comb_sort(nums):
    if not nums:
        return nums

    n = len(nums)
    gap = n
    swapped = True

    while gap > 1 or swapped:
        gap = max(1, int(gap / 1.3))
        swapped = False

        for i in range(n - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                swapped = True

    return nums
